mapper.update:
UPDATE t_work_order

    status = #{targetStatus},
    version = version + 1,
    update_time = NOW()
    , assignee_id = #{fields.assigneeId}
    , dispatch_type = #{fields.dispatchType}
    , assign_time = #{fields.assignTime}
    , accept_time = #{fields.acceptTime}
    , arrive_time = #{fields.arriveTime}
    , finish_time = #{fields.finishTime}
    , confirm_time = #{fields.confirmTime}
    , close_time = #{fields.closeTime}
    , cancel_time = #{fields.cancelTime}
    , cancel_reason = #{fields.cancelReason}
    , priority = #{fields.priority}
    , current_round = #{fields.currentRound}
    , expect_hours = #{fields.expectHours}
    , deadline_time = #{fields.deadlineTime}
    , timeout_flag = #{fields.timeoutFlag}
    , timeout_type = #{fields.timeoutType}
    , evaluate_flag = #{fields.evaluateFlag}

WHERE id = #{orderId}
  AND status = #{currentStatus}
  AND deleted = 0
